import{S as e,h as t,m as n,t as r}from"./app-BNK-he3q.js";var i=JSON.parse(`{"path":"/guide/ci-cd-deploy/","title":"CI/CD и деплой","lang":"ru-RU","frontmatter":{"prev":"/guide/sql-postgresql/best-practices.md","next":"/guide/ci-cd-deploy/tests.md"},"git":{"updatedTime":1792784001000,"contributors":[{"name":"Danil Chugaev","username":"","email":"danilchugaev@mail.ru","commits":1}],"changelog":[{"hash":"366d31f9528b484791c72de900ce30150c49cf72","time":1792784001000,"email":"danilchugaev@mail.ru","author":"Danil Chugaev","message":"perf: unblocked css"}]},"filePathRelative":"guide/ci-cd-deploy/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="ci-cd-и-деплои" tabindex="-1"><a class="header-anchor" href="#ci-cd-и-деплои"><span>CI/CD и деплой</span></a></h1><h2 id="цель-урока" tabindex="-1"><a class="header-anchor" href="#цель-урока"><span>Цель урока</span></a></h2><p>Настроить для Task Manager API GitHub Actions: автоматически запускать проверку Go-кода и PostgreSQL integration-тесты, собирать Docker-образ, публиковать проверенный образ в GitHub Container Registry (GHCR) и безопасно доставлять его на VPS через Docker Compose с health-check и возможностью отката.</p><p><strong>CI</strong> (continuous integration) отвечает на вопрос «можно ли объединить это изменение?»: собирает проект и запускает проверки. <strong>CD</strong> (continuous delivery/deployment) отвечает на вопрос «как доставить уже проверенный образ в окружение?». Сначала сделаем CI надёжным, затем отдельно подготовим delivery и deployment.</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">pull request / push</span>
<span class="line">        ↓</span>
<span class="line">GitHub Actions: vet → unit/race → PostgreSQL integration → Docker build</span>
<span class="line">        ↓</span>
<span class="line">GHCR: неизменяемый Docker image по SHA commit</span>
<span class="line">        ↓</span>
<span class="line">VPS: docker compose pull/up → /healthz → rollback при проблеме</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="что-должно-быть-до-ci" tabindex="-1"><a class="header-anchor" href="#что-должно-быть-до-ci"><span>Что должно быть до CI</span></a></h2><p>Финальный Task Manager API должен содержать:</p><ul><li><code>go.mod</code> и <code>go.sum</code>;</li><li>unit-тесты, запускаемые через <code>go test ./...</code>;</li><li>миграции Goose в <code>migrations/</code>;</li><li>integration-тесты PostgreSQL с build tag <code>integration</code>;</li><li><code>Dockerfile</code>;</li><li>endpoint <code>GET /healthz</code>;</li><li><code>compose.production.yaml</code> для VPS.</li></ul><p>Не копируйте workflow в учебник как есть, если пути и имя модуля отличаются. Сначала запустите все команды локально — CI должен автоматизировать уже работающий workflow, а не заменять отладку.</p><h2 id="ci-unit-тесты-race-detector-и-docker-build" tabindex="-1"><a class="header-anchor" href="#ci-unit-тесты-race-detector-и-docker-build"><span>CI: unit-тесты, race detector и Docker build</span></a></h2><p>Создайте <code>.github/workflows/ci.yml</code> в репозитории <strong>Task Manager API</strong>:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">name</span><span class="token punctuation">:</span> CI</span>
<span class="line"></span>
<span class="line"><span class="token key atrule">on</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">push</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">branches</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>master<span class="token punctuation">]</span></span>
<span class="line">  <span class="token key atrule">pull_request</span><span class="token punctuation">:</span></span>
<span class="line"></span>
<span class="line"><span class="token key atrule">permissions</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">contents</span><span class="token punctuation">:</span> read</span>
<span class="line"></span>
<span class="line"><span class="token key atrule">jobs</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">unit</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">name</span><span class="token punctuation">:</span> Unit tests and static checks</span>
<span class="line">    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest</span>
<span class="line">    <span class="token key atrule">steps</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4</span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/setup<span class="token punctuation">-</span>go@v5</span>
<span class="line">        <span class="token key atrule">with</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token key atrule">go-version-file</span><span class="token punctuation">:</span> go.mod</span>
<span class="line">          <span class="token key atrule">cache</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Check module files</span>
<span class="line">        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string"></span>
<span class="line">          go mod tidy</span>
<span class="line">          git diff --exit-code -- go.mod go.sum</span></span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Vet</span>
<span class="line">        <span class="token key atrule">run</span><span class="token punctuation">:</span> go vet ./<span class="token punctuation">...</span></span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Unit tests with race detector</span>
<span class="line">        <span class="token key atrule">run</span><span class="token punctuation">:</span> go test <span class="token punctuation">-</span>race ./<span class="token punctuation">...</span></span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Build API</span>
<span class="line">        <span class="token key atrule">run</span><span class="token punctuation">:</span> go build ./cmd/api</span>
<span class="line"></span>
<span class="line">  <span class="token key atrule">docker</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">name</span><span class="token punctuation">:</span> Docker build</span>
<span class="line">    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest</span>
<span class="line">    <span class="token key atrule">needs</span><span class="token punctuation">:</span> unit</span>
<span class="line">    <span class="token key atrule">steps</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4</span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Validate Compose configuration</span>
<span class="line">        <span class="token key atrule">working-directory</span><span class="token punctuation">:</span> examples/32/task<span class="token punctuation">-</span>manager<span class="token punctuation">-</span>api</span>
<span class="line">        <span class="token key atrule">run</span><span class="token punctuation">:</span> docker compose config</span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Build image</span>
<span class="line">        <span class="token key atrule">working-directory</span><span class="token punctuation">:</span> examples/32/task<span class="token punctuation">-</span>manager<span class="token punctuation">-</span>api</span>
<span class="line">        <span class="token key atrule">run</span><span class="token punctuation">:</span> docker build <span class="token punctuation">-</span><span class="token punctuation">-</span>tag task<span class="token punctuation">-</span>manager<span class="token punctuation">-</span>api<span class="token punctuation">:</span>ci .</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>go mod tidy</code> <strong>может менять</strong> <code>go.mod</code> и <code>go.sum</code>, поэтому сразу после него выполняется <code>git diff --exit-code</code>. Так CI не только сообщает, что файлы модулей неактуальны, но и не оставляет незаметное изменение в runner.</p><p>Docker build зависит от <code>unit</code>: нет смысла тратить время на сборку образа, если код не прошёл статический анализ или тесты. В production workflow можно использовать cache BuildKit, но сначала добейтесь воспроизводимой простой сборки.</p><h2 id="postgresql-integration-тесты-в-github-actions" tabindex="-1"><a class="header-anchor" href="#postgresql-integration-тесты-в-github-actions"><span>PostgreSQL integration-тесты в GitHub Actions</span></a></h2><p>Для integration-тестов используем service container PostgreSQL. Он живёт только во время job и не требует Docker Compose или отдельной тестовой инфраструктуры:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line">  <span class="token key atrule">integration</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">name</span><span class="token punctuation">:</span> PostgreSQL integration tests</span>
<span class="line">    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest</span>
<span class="line">    <span class="token key atrule">needs</span><span class="token punctuation">:</span> unit</span>
<span class="line">    <span class="token key atrule">services</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">postgres</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token key atrule">image</span><span class="token punctuation">:</span> postgres<span class="token punctuation">:</span>17<span class="token punctuation">-</span>alpine</span>
<span class="line">        <span class="token key atrule">env</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token key atrule">POSTGRES_DB</span><span class="token punctuation">:</span> task_manager_test</span>
<span class="line">          <span class="token key atrule">POSTGRES_USER</span><span class="token punctuation">:</span> task_manager</span>
<span class="line">          <span class="token key atrule">POSTGRES_PASSWORD</span><span class="token punctuation">:</span> test<span class="token punctuation">-</span>password<span class="token punctuation">-</span>only</span>
<span class="line">        <span class="token key atrule">ports</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token punctuation">-</span> 5432<span class="token punctuation">:</span><span class="token number">5432</span></span>
<span class="line">        <span class="token key atrule">options</span><span class="token punctuation">:</span> <span class="token punctuation">&gt;</span><span class="token punctuation">-</span></span>
<span class="line">          <span class="token punctuation">-</span><span class="token punctuation">-</span>health<span class="token punctuation">-</span>cmd &quot;pg_isready <span class="token punctuation">-</span>U task_manager <span class="token punctuation">-</span>d task_manager_test&quot;</span>
<span class="line">          <span class="token punctuation">-</span><span class="token punctuation">-</span>health<span class="token punctuation">-</span>interval 5s</span>
<span class="line">          <span class="token punctuation">-</span><span class="token punctuation">-</span>health<span class="token punctuation">-</span>timeout 3s</span>
<span class="line">          <span class="token punctuation">-</span><span class="token punctuation">-</span>health<span class="token punctuation">-</span>retries 10</span>
<span class="line"></span>
<span class="line">    <span class="token key atrule">env</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">TEST_DATABASE_URL</span><span class="token punctuation">:</span> postgresql<span class="token punctuation">:</span>//task_manager<span class="token punctuation">:</span>test<span class="token punctuation">-</span>password<span class="token punctuation">-</span>only@localhost<span class="token punctuation">:</span>5432/task_manager_test<span class="token punctuation">?</span>sslmode=disable</span>
<span class="line"></span>
<span class="line">    <span class="token key atrule">steps</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4</span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/setup<span class="token punctuation">-</span>go@v5</span>
<span class="line">        <span class="token key atrule">with</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token key atrule">go-version-file</span><span class="token punctuation">:</span> go.mod</span>
<span class="line">          <span class="token key atrule">cache</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Install Goose</span>
<span class="line">        <span class="token key atrule">run</span><span class="token punctuation">:</span> go install github.com/pressly/goose/v3/cmd/goose@v3.29.0</span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Apply migrations</span>
<span class="line">        <span class="token key atrule">run</span><span class="token punctuation">:</span> $HOME/go/bin/goose <span class="token punctuation">-</span>dir migrations postgres &quot;$TEST_DATABASE_URL&quot; up</span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Integration tests</span>
<span class="line">        <span class="token key atrule">run</span><span class="token punctuation">:</span> go test <span class="token punctuation">-</span>race <span class="token punctuation">-</span>count=1 <span class="token punctuation">-</span>tags=integration ./internal/postgresrepo/<span class="token punctuation">...</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Пароль в этом примере не секрет: это одноразовая тестовая БД внутри ephemeral runner. Настоящие пароли, токены и SSH-ключи никогда не записывают прямо в workflow — для них используются GitHub Actions Secrets.</p><p>Тесты должны обращаться только к <code>TEST_DATABASE_URL</code>. Проверка имени базы с суффиксом <code>_test</code> из прошлой главы остаётся дополнительной защитой от разрушительного <code>TRUNCATE</code> не той базы.</p><p><code>-count=1</code> отключает тестовый кэш: integration-тест действительно выполняется против service container. Команда <code>go test -race</code> медленнее обычной, но для небольшого backend-проекта это оправданная проверка конкурентных ошибок.</p><h2 id="матрица-проверок" tabindex="-1"><a class="header-anchor" href="#матрица-проверок"><span>Матрица проверок</span></a></h2><table><thead><tr><th>Job</th><th>Что подтверждает</th><th>Чего не подтверждает</th></tr></thead><tbody><tr><td><code>unit</code></td><td>компиляцию, unit-тесты, race detector, актуальность модулей</td><td>реальный SQL PostgreSQL</td></tr><tr><td><code>integration</code></td><td>миграции, SQL, constraints и PostgreSQL-репозиторий</td><td>production-конфигурацию VPS</td></tr><tr><td><code>docker</code></td><td>Dockerfile и Compose YAML</td><td>работоспособность приложения после запуска образа</td></tr><tr><td>deployment</td><td>доставку конкретного образа и <code>/healthz</code></td><td>полную бизнес-нагрузку production</td></tr></tbody></table><p>Каждый job нужен для отдельного риска. Не заменяйте PostgreSQL-тесты проверкой <code>docker build</code>, а health-check после деплоя — unit-тестами.</p><h2 id="публикация-образа-в-ghcr" tabindex="-1"><a class="header-anchor" href="#публикация-образа-в-ghcr"><span>Публикация образа в GHCR</span></a></h2><p>GitHub Container Registry хранит Docker-образы рядом с репозиторием. Публикуйте только образ, прошедший CI, и маркируйте его неизменяемым SHA commit. <code>latest</code> удобен для просмотра, но не годится как единственный production-тег: по нему нельзя понять, какой именно код работает и как откатиться.</p><p>Создайте <code>.github/workflows/publish-image.yml</code>:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">name</span><span class="token punctuation">:</span> Publish image</span>
<span class="line"></span>
<span class="line"><span class="token key atrule">on</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">push</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">branches</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>master<span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line"><span class="token key atrule">permissions</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">contents</span><span class="token punctuation">:</span> read</span>
<span class="line">  <span class="token key atrule">packages</span><span class="token punctuation">:</span> write</span>
<span class="line"></span>
<span class="line"><span class="token key atrule">env</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token comment"># GitHub image names должны быть lowercase.</span></span>
<span class="line">  <span class="token key atrule">IMAGE_NAME</span><span class="token punctuation">:</span> ghcr.io/danilchugaev/task<span class="token punctuation">-</span>manager<span class="token punctuation">-</span>api</span>
<span class="line"></span>
<span class="line"><span class="token key atrule">jobs</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">publish</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest</span>
<span class="line">    <span class="token key atrule">steps</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4</span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> docker/setup<span class="token punctuation">-</span>buildx<span class="token punctuation">-</span>action@v3</span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> docker/login<span class="token punctuation">-</span>action@v3</span>
<span class="line">        <span class="token key atrule">with</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token key atrule">registry</span><span class="token punctuation">:</span> ghcr.io</span>
<span class="line">          <span class="token key atrule">username</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> github.actor <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line">          <span class="token key atrule">password</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> secrets.GITHUB_TOKEN <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">id</span><span class="token punctuation">:</span> meta</span>
<span class="line">        <span class="token key atrule">uses</span><span class="token punctuation">:</span> docker/metadata<span class="token punctuation">-</span>action@v5</span>
<span class="line">        <span class="token key atrule">with</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token key atrule">images</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> env.IMAGE_NAME <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line">          <span class="token key atrule">tags</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string"></span>
<span class="line">            type=raw,value=latest</span>
<span class="line">            type=sha,format=long</span></span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> docker/build<span class="token punctuation">-</span>push<span class="token punctuation">-</span>action@v6</span>
<span class="line">        <span class="token key atrule">with</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token key atrule">context</span><span class="token punctuation">:</span> .</span>
<span class="line">          <span class="token key atrule">push</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line">          <span class="token key atrule">tags</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> steps.meta.outputs.tags <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line">          <span class="token key atrule">labels</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> steps.meta.outputs.labels <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Замените <code>danilchugaev/task-manager-api</code> на lowercase-имя владельца и образа вашего конечного API. Если registry package закрыт, VPS понадобится токен с разрешением <code>read:packages</code>; не используйте personal token с избыточными правами.</p><div class="hint-container warning"><p class="hint-container-title">Не публикуйте образ до CI</p><p>Самостоятельный publish workflow запускается на <code>push</code>, но GitHub Actions не гарантирует порядок разных workflow. Для строгого правила «publish только после зелёного CI» объедините CI и publish в один workflow: job <code>publish</code> должен иметь <code>needs: [unit, integration, docker]</code>. Альтернатива — запускать publish только после защищённого merge в <code>master</code>, где branch protection требует успешный CI.</p></div><p>Практический вариант одного workflow:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line">  <span class="token key atrule">publish</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">needs</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>unit<span class="token punctuation">,</span> integration<span class="token punctuation">,</span> docker<span class="token punctuation">]</span></span>
<span class="line">    <span class="token key atrule">if</span><span class="token punctuation">:</span> github.event_name == &#39;push&#39; <span class="token important">&amp;&amp;</span> github.ref == &#39;refs/heads/master&#39;</span>
<span class="line">    <span class="token comment"># login, metadata и build-push-action здесь</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Это безопаснее для первого production-проекта, потому что зависимость job выражена явно.</p><h2 id="production-compose-на-vps" tabindex="-1"><a class="header-anchor" href="#production-compose-на-vps"><span>Production Compose на VPS</span></a></h2><p>На VPS создайте каталог, например <code>/opt/task-manager</code>, и поместите туда <code>compose.production.yaml</code> и закрытый <code>.env</code>:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">services</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">api</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">image</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span>IMAGE<span class="token punctuation">:</span><span class="token punctuation">?</span>IMAGE is required<span class="token punctuation">}</span></span>
<span class="line">    <span class="token key atrule">env_file</span><span class="token punctuation">:</span> .env</span>
<span class="line">    <span class="token key atrule">depends_on</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">postgres</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token key atrule">condition</span><span class="token punctuation">:</span> service_healthy</span>
<span class="line">    <span class="token key atrule">ports</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token comment"># Reverse proxy на том же сервере обращается к API локально.</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">&quot;127.0.0.1:8080:8080&quot;</span></span>
<span class="line">    <span class="token key atrule">restart</span><span class="token punctuation">:</span> unless<span class="token punctuation">-</span>stopped</span>
<span class="line"></span>
<span class="line">  <span class="token key atrule">postgres</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">image</span><span class="token punctuation">:</span> postgres<span class="token punctuation">:</span>17<span class="token punctuation">-</span>alpine</span>
<span class="line">    <span class="token key atrule">env_file</span><span class="token punctuation">:</span> .env</span>
<span class="line">    <span class="token key atrule">environment</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">POSTGRES_DB</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span>POSTGRES_DB<span class="token punctuation">}</span></span>
<span class="line">      <span class="token key atrule">POSTGRES_USER</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span>POSTGRES_USER<span class="token punctuation">}</span></span>
<span class="line">      <span class="token key atrule">POSTGRES_PASSWORD</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span>POSTGRES_PASSWORD<span class="token punctuation">}</span></span>
<span class="line">    <span class="token key atrule">volumes</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> postgres<span class="token punctuation">-</span>data<span class="token punctuation">:</span>/var/lib/postgresql/data</span>
<span class="line">    <span class="token key atrule">healthcheck</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token key atrule">test</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&quot;CMD-SHELL&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;pg_isready -U $$POSTGRES_USER -d $$POSTGRES_DB&quot;</span><span class="token punctuation">]</span></span>
<span class="line">      <span class="token key atrule">interval</span><span class="token punctuation">:</span> 5s</span>
<span class="line">      <span class="token key atrule">timeout</span><span class="token punctuation">:</span> 3s</span>
<span class="line">      <span class="token key atrule">retries</span><span class="token punctuation">:</span> <span class="token number">10</span></span>
<span class="line">    <span class="token key atrule">restart</span><span class="token punctuation">:</span> unless<span class="token punctuation">-</span>stopped</span>
<span class="line"></span>
<span class="line"><span class="token key atrule">volumes</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">postgres-data</span><span class="token punctuation">:</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>В production у PostgreSQL <strong>нет</strong> <code>ports</code>: он доступен только в сети Compose. API опубликован лишь на <code>127.0.0.1</code>; внешний HTTPS-трафик принимает отдельный reverse proxy (например, Caddy или Nginx). TLS, домен и reverse proxy заслуживают отдельной настройки, поэтому не выдавайте HTTP-порт API напрямую в интернет как финальное решение.</p><p>Пример закрытого <code>/opt/task-manager/.env</code>:</p><div class="language-dotenv line-numbers-mode" data-highlighter="prismjs" data-ext="dotenv"><pre><code class="language-dotenv"><span class="line">POSTGRES_DB=task_manager</span>
<span class="line">POSTGRES_USER=task_manager</span>
<span class="line">POSTGRES_PASSWORD=replace-with-a-long-random-secret</span>
<span class="line">DATABASE_URL=postgresql://task_manager:replace-with-a-long-random-secret@postgres:5432/task_manager?sslmode=disable</span>
<span class="line">PRIORITY_SERVICE_URL=https://priority.example.com</span>
<span class="line">SHUTDOWN_TIMEOUT=10s</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Файл принадлежит пользователю деплоя и имеет ограниченные права:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">chmod</span> <span class="token number">600</span> /opt/task-manager/.env</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Не коммитьте production <code>.env</code>, не копируйте его в Docker image и не выводите командой <code>docker compose config</code> в публичные CI-логи: результат содержит подставленные secrets.</p><h2 id="первыи-деплои-и-проверка" tabindex="-1"><a class="header-anchor" href="#первыи-деплои-и-проверка"><span>Первый деплой и проверка</span></a></h2><p>На VPS сначала авторизуйтесь в GHCR. Для private image создайте отдельный токен только с <code>read:packages</code> и передайте его через stdin:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">printf</span> <span class="token string">&#39;%s&#39;</span> <span class="token string">&quot;<span class="token variable">$GHCR_READ_TOKEN</span>&quot;</span> <span class="token operator">|</span> <span class="token function">docker</span> login ghcr.io <span class="token parameter variable">-u</span> <span class="token string">&quot;<span class="token variable">$GHCR_USER</span>&quot;</span> --password-stdin</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Затем разверните конкретный immutable image:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">cd</span> /opt/task-manager</span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">IMAGE</span><span class="token operator">=</span>ghcr.io/danilchugaev/task-manager-api:sha-0123456789abcdef</span>
<span class="line"><span class="token function">docker</span> compose <span class="token parameter variable">-f</span> compose.production.yaml pull api</span>
<span class="line"><span class="token function">docker</span> compose <span class="token parameter variable">-f</span> compose.production.yaml up <span class="token parameter variable">-d</span></span>
<span class="line"></span>
<span class="line"><span class="token function">curl</span> <span class="token parameter variable">--fail</span> <span class="token parameter variable">--retry</span> <span class="token number">10</span> --retry-connrefused --retry-delay <span class="token number">1</span> <span class="token punctuation">\\</span></span>
<span class="line">  http://127.0.0.1:8080/healthz</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>curl --fail</code> возвращает ненулевой код на <code>4xx</code>/<code>5xx</code>, поэтому команда подходит для проверки после delivery. Сохраняйте SHA-тег успешной версии в release notes или deploy-логе.</p><h2 id="откат" tabindex="-1"><a class="header-anchor" href="#откат"><span>Откат</span></a></h2><p>Откат должен использовать предыдущий известный рабочий immutable тег, а не <code>latest</code>:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">cd</span> /opt/task-manager</span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">IMAGE</span><span class="token operator">=</span>ghcr.io/danilchugaev/task-manager-api:sha-previous-known-good</span>
<span class="line"><span class="token function">docker</span> compose <span class="token parameter variable">-f</span> compose.production.yaml pull api</span>
<span class="line"><span class="token function">docker</span> compose <span class="token parameter variable">-f</span> compose.production.yaml up <span class="token parameter variable">-d</span> --no-deps api</span>
<span class="line"></span>
<span class="line"><span class="token function">curl</span> <span class="token parameter variable">--fail</span> http://127.0.0.1:8080/healthz</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Откат образа не откатывает схему PostgreSQL. Поэтому миграции должны быть backward-compatible в течение времени, когда возможен rollback: например, сначала добавить nullable столбец, затем обновить приложение, а удалять старый столбец отдельным поздним релизом.</p><h2 id="автоматическии-deployment-workflow" tabindex="-1"><a class="header-anchor" href="#автоматическии-deployment-workflow"><span>Автоматический deployment workflow</span></a></h2><p>Когда ручной деплой понятен и проверен, его можно запускать из GitHub Actions. Не добавляйте ключ VPS в репозиторий. Создайте GitHub Secrets:</p><table><thead><tr><th>Secret</th><th>Назначение</th></tr></thead><tbody><tr><td><code>VPS_HOST</code></td><td>hostname или IP сервера</td></tr><tr><td><code>VPS_USER</code></td><td>отдельный пользователь деплоя без root-логина</td></tr><tr><td><code>VPS_SSH_PRIVATE_KEY</code></td><td>приватный SSH-ключ только для deploy user</td></tr><tr><td><code>VPS_KNOWN_HOSTS</code></td><td>заранее проверенный fingerprint/known_hosts сервера</td></tr></tbody></table><p>Фрагмент <code>.github/workflows/deploy.yml</code>:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line">  <span class="token key atrule">deploy</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">needs</span><span class="token punctuation">:</span> publish</span>
<span class="line">    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest</span>
<span class="line">    <span class="token key atrule">environment</span><span class="token punctuation">:</span> production</span>
<span class="line">    <span class="token key atrule">steps</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Configure SSH</span>
<span class="line">        <span class="token key atrule">env</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token key atrule">SSH_KEY</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> secrets.VPS_SSH_PRIVATE_KEY <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line">          <span class="token key atrule">KNOWN_HOSTS</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> secrets.VPS_KNOWN_HOSTS <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line">        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string"></span>
<span class="line">          install -m 700 -d ~/.ssh</span>
<span class="line">          printf &#39;%s\\n&#39; &quot;$SSH_KEY&quot; &gt; ~/.ssh/id_ed25519</span>
<span class="line">          chmod 600 ~/.ssh/id_ed25519</span>
<span class="line">          printf &#39;%s\\n&#39; &quot;$KNOWN_HOSTS&quot; &gt; ~/.ssh/known_hosts</span></span>
<span class="line"></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Deploy immutable image</span>
<span class="line">        <span class="token key atrule">env</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token key atrule">HOST</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> secrets.VPS_HOST <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line">          <span class="token key atrule">USER</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> secrets.VPS_USER <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line">          <span class="token key atrule">IMAGE</span><span class="token punctuation">:</span> ghcr.io/danilchugaev/task<span class="token punctuation">-</span>manager<span class="token punctuation">-</span>api<span class="token punctuation">:</span>sha<span class="token punctuation">-</span>$<span class="token punctuation">{</span><span class="token punctuation">{</span> github.sha <span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line">        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string"></span>
<span class="line">          ssh &quot;$USER@$HOST&quot; &quot;</span>
<span class="line">            set -eu</span>
<span class="line">            cd /opt/task-manager</span>
<span class="line">            export IMAGE=&#39;$IMAGE&#39;</span>
<span class="line">            docker compose -f compose.production.yaml pull api</span>
<span class="line">            docker compose -f compose.production.yaml up -d --no-deps api</span>
<span class="line">            curl --fail --retry 10 --retry-connrefused --retry-delay 1 http://127.0.0.1:8080/healthz</span>
<span class="line">          &quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Environment <code>production</code> позволяет настроить required reviewers и отдельные environment secrets в GitHub. <code>VPS_KNOWN_HOSTS</code> важен: не заменяйте проверку хоста на <code>StrictHostKeyChecking=no</code>, иначе workflow становится уязвимым к подмене SSH-сервера.</p><p>Автоматический deploy не отменяет rollback-план. Перед включением workflow вручную проверьте: доступ VPS к GHCR, права deploy user на Docker, наличие <code>.env</code>, volume PostgreSQL, reverse proxy и health-check.</p><h2 id="частые-ошибки" tabindex="-1"><a class="header-anchor" href="#частые-ошибки"><span>Частые ошибки</span></a></h2><h3 id="заменить-ci-одним-go-test" tabindex="-1"><a class="header-anchor" href="#заменить-ci-одним-go-test"><span>Заменить CI одним <code>go test ./...</code></span></a></h3><p>Так не проверятся <code>go vet</code>, гонки, миграции, SQL-привязка к PostgreSQL и Dockerfile. Разделите unit, integration и image build на явные jobs.</p><h3 id="передать-production-пароль-в-yaml-workflow" tabindex="-1"><a class="header-anchor" href="#передать-production-пароль-в-yaml-workflow"><span>Передать production пароль в YAML workflow</span></a></h3><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">env</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">DATABASE_URL</span><span class="token punctuation">:</span> postgresql<span class="token punctuation">:</span>//user<span class="token punctuation">:</span>real<span class="token punctuation">-</span>password@host/database</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Это секрет в истории Git. Используйте GitHub Secrets для CI/CD и закрытый <code>.env</code> с правами <code>600</code> на VPS.</p><h3 id="деплоить-latest" tabindex="-1"><a class="header-anchor" href="#деплоить-latest"><span>Деплоить <code>latest</code></span></a></h3><p><code>latest</code> меняется при каждом publish и не задаёт точную версию. Деплойте SHA-тег и сохраняйте предыдущий рабочий SHA для rollback.</p><h3 id="публиковать-postgresql-наружу-на-vps" tabindex="-1"><a class="header-anchor" href="#публиковать-postgresql-наружу-на-vps"><span>Публиковать PostgreSQL наружу на VPS</span></a></h3><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">ports</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token punctuation">-</span> <span class="token string">&quot;5432:5432&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Это увеличивает поверхность атаки. Для API и PostgreSQL достаточно внутренней Compose-сети; внешний доступ организуют только при осознанной необходимости и защите.</p><h3 id="откатывать-код-после-несовместимои-миграции" tabindex="-1"><a class="header-anchor" href="#откатывать-код-после-несовместимои-миграции"><span>Откатывать код после несовместимой миграции</span></a></h3><p>Предыдущий image может ожидать старую схему. Делайте миграции совместимыми в несколько этапов и планируйте их вместе с rollback.</p><h2 id="дальше" tabindex="-1"><a class="header-anchor" href="#дальше"><span>Дальше</span></a></h2><p>Task Manager теперь имеет CI, проверяемый image и понятный путь доставки на VPS. Последняя глава соберёт все части проекта вместе: структура репозитория, README, запуск, примеры API и итоговый чек-лист качества.</p>`,73)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};